entry.string:
$ErrorActionPreference = 'Stop' $log = Join-Path $env:PROJECT_DIR 'target\parabank-cargo.log' $err = Join-Path $env:PROJECT_DIR 'target\parabank-cargo.err' Remove-Item $log, $err -Force -ErrorAction SilentlyContinue
$mvn = (Get-Command mvn.cmd -ErrorAction SilentlyContinue).Source if (-not $mvn) { $mvn = (Get-Command mvn -ErrorAction Stop).Source }
Start-Process ` -FilePath $mvn ` -ArgumentList @('-DskipTests', "${env:CARGO_GOAL}:run") ` -WorkingDirectory $env:PROJECT_DIR ` -RedirectStandardOutput $log ` -RedirectStandardError $err ` -WindowStyle Hidden

$ports = @(8080, 8205, 9001)
foreach ($port in $ports) {
    Get-NetTCPConnection -LocalPort $port -ErrorAction SilentlyContinue |
        Select-Object -ExpandProperty OwningProcess -Unique |
        ForEach-Object {
            Stop-Process -Id $_ -Force -ErrorAction SilentlyContinue
        }
}
